-- Cybersecurity-Academy full schema (generated by `php bin/console schema:dump`).
-- Prefer `php bin/console migrate` which also tracks applied versions.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 001_identity_and_access.sql
-- 001: Users, RBAC, authentication support, settings, audit trail.

CREATE TABLE users (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(190) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    display_name VARCHAR(120) NOT NULL,
    locale ENUM('en','fr') NOT NULL DEFAULT 'en',
    content_locale ENUM('en','fr') NULL COMMENT 'NULL = follow interface language',
    status ENUM('active','suspended','deleted') NOT NULL DEFAULT 'active',
    auth_version INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Incremented on password change to invalidate sessions',
    email_verified_at DATETIME NULL,
    public_profile TINYINT(1) NOT NULL DEFAULT 0,
    public_slug VARCHAR(64) NULL,
    show_progress_public TINYINT(1) NOT NULL DEFAULT 0,
    headline VARCHAR(160) NULL,
    last_login_at DATETIME NULL,
    deletion_requested_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_users_email (email),
    UNIQUE KEY uq_users_public_slug (public_slug),
    KEY idx_users_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE roles (
    id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(40) NOT NULL,
    name VARCHAR(80) NOT NULL,
    UNIQUE KEY uq_roles_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE permissions (
    id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(80) NOT NULL,
    description VARCHAR(190) NOT NULL,
    UNIQUE KEY uq_permissions_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE role_permissions (
    role_id SMALLINT UNSIGNED NOT NULL,
    permission_id SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (role_id, permission_id),
    CONSTRAINT fk_rp_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
    CONSTRAINT fk_rp_perm FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE user_roles (
    user_id BIGINT UNSIGNED NOT NULL,
    role_id SMALLINT UNSIGNED NOT NULL,
    assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, role_id),
    CONSTRAINT fk_ur_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_ur_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE password_resets (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    token_hash CHAR(64) NOT NULL COMMENT 'SHA-256 of the token; the raw token is only e-mailed',
    expires_at DATETIME NOT NULL,
    used_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_password_resets_token (token_hash),
    KEY idx_password_resets_user (user_id),
    CONSTRAINT fk_pr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE login_attempts (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(190) NOT NULL,
    ip_address VARCHAR(45) NOT NULL,
    user_agent VARCHAR(255) NULL,
    succeeded TINYINT(1) NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_login_attempts_email (email, created_at),
    KEY idx_login_attempts_ip (ip_address, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE rate_limits (
    limiter_key CHAR(64) PRIMARY KEY,
    hits INT UNSIGNED NOT NULL DEFAULT 0,
    reset_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE platform_settings (
    setting_key VARCHAR(80) PRIMARY KEY,
    setting_value TEXT NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE audit_logs (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    actor_id BIGINT UNSIGNED NULL,
    action VARCHAR(80) NOT NULL,
    entity_type VARCHAR(60) NULL,
    entity_id VARCHAR(64) NULL,
    details JSON NULL,
    ip_address VARCHAR(45) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_audit_actor (actor_id),
    KEY idx_audit_action (action),
    KEY idx_audit_entity (entity_type, entity_id),
    KEY idx_audit_created (created_at),
    CONSTRAINT fk_audit_actor FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE notifications (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    type VARCHAR(60) NOT NULL,
    data JSON NOT NULL COMMENT 'Translation key + parameters, rendered in the reader''s language',
    link VARCHAR(255) NULL,
    read_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_notifications_user (user_id, read_at),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 002_learning_content.sql
-- 002: Learning paths, courses, modules, lessons (all with EN/FR translations),
-- resources, enrolments and progress.

CREATE TABLE learning_paths (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(10) NOT NULL COMMENT 'Used in certificate numbers, e.g. SOC',
    slug VARCHAR(80) NOT NULL,
    accent VARCHAR(20) NOT NULL DEFAULT 'blue',
    icon VARCHAR(40) NOT NULL DEFAULT 'shield',
    sort_order SMALLINT NOT NULL DEFAULT 0,
    is_published TINYINT(1) NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_paths_code (code),
    UNIQUE KEY uq_paths_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE learning_path_translations (
    path_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(160) NOT NULL,
    tagline VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    career_outcomes TEXT NULL COMMENT 'One outcome per line',
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    PRIMARY KEY (path_id, locale),
    CONSTRAINT fk_lpt_path FOREIGN KEY (path_id) REFERENCES learning_paths(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE courses (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(120) NOT NULL,
    level ENUM('beginner','intermediate','advanced','all') NOT NULL DEFAULT 'beginner',
    access_level ENUM('free','premium') NOT NULL DEFAULT 'premium',
    price_cents INT UNSIGNED NOT NULL DEFAULT 0,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    estimated_hours SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    status ENUM('draft','in_review','published','archived') NOT NULL DEFAULT 'draft',
    is_featured TINYINT(1) NOT NULL DEFAULT 0,
    min_exam_score TINYINT UNSIGNED NOT NULL DEFAULT 70 COMMENT 'Completion rule: final exam passing %',
    require_all_labs TINYINT(1) NOT NULL DEFAULT 1 COMMENT 'Completion rule: required labs must be passed',
    certificate_enabled TINYINT(1) NOT NULL DEFAULT 1,
    created_by BIGINT UNSIGNED NULL,
    published_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_courses_slug (slug),
    KEY idx_courses_status (status, is_featured),
    CONSTRAINT fk_courses_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE course_translations (
    course_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    subtitle VARCHAR(255) NOT NULL DEFAULT '',
    description TEXT NOT NULL,
    outcomes TEXT NULL COMMENT 'One learning outcome per line',
    audience TEXT NULL,
    certificate_title VARCHAR(190) NULL,
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (course_id, locale),
    FULLTEXT KEY ft_course_translations (title, subtitle, description),
    CONSTRAINT fk_ct_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE learning_path_courses (
    path_id INT UNSIGNED NOT NULL,
    course_id INT UNSIGNED NOT NULL,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    is_required TINYINT(1) NOT NULL DEFAULT 1,
    PRIMARY KEY (path_id, course_id),
    KEY idx_lpc_course (course_id),
    CONSTRAINT fk_lpc_path FOREIGN KEY (path_id) REFERENCES learning_paths(id) ON DELETE CASCADE,
    CONSTRAINT fk_lpc_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE modules (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    course_id INT UNSIGNED NOT NULL,
    slug VARCHAR(120) NOT NULL,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    level ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'beginner',
    status ENUM('draft','in_review','published','archived') NOT NULL DEFAULT 'draft',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_modules_course_slug (course_id, slug),
    KEY idx_modules_course (course_id, sort_order),
    CONSTRAINT fk_modules_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE module_translations (
    module_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    summary TEXT NOT NULL,
    topics TEXT NULL COMMENT 'Syllabus topics, one per line',
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    PRIMARY KEY (module_id, locale),
    CONSTRAINT fk_mt_module FOREIGN KEY (module_id) REFERENCES modules(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lessons (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    module_id INT UNSIGNED NOT NULL,
    slug VARCHAR(120) NOT NULL,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    chapter_number SMALLINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Chapter grouping inside a module',
    level ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'beginner',
    duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 30,
    is_required TINYINT(1) NOT NULL DEFAULT 1,
    is_preview TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'Readable by signed-in users without enrolment',
    status ENUM('draft','in_review','published','archived') NOT NULL DEFAULT 'draft',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_lessons_module_slug (module_id, slug),
    KEY idx_lessons_module (module_id, sort_order),
    KEY idx_lessons_status (status),
    CONSTRAINT fk_lessons_module FOREIGN KEY (module_id) REFERENCES modules(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lesson_translations (
    lesson_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    chapter_title VARCHAR(190) NULL,
    summary TEXT NOT NULL,
    objectives TEXT NULL COMMENT 'One objective per line',
    prerequisites TEXT NULL COMMENT 'One prerequisite per line',
    content MEDIUMTEXT NOT NULL COMMENT 'Markdown, rendered with HTML escaping',
    assignment TEXT NULL,
    completion_criteria TEXT NULL,
    references_md TEXT NULL,
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    reviewed_by BIGINT UNSIGNED NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (lesson_id, locale),
    CONSTRAINT fk_lt_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,
    CONSTRAINT fk_lt_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE enrollments (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    course_id INT UNSIGNED NOT NULL,
    access_source ENUM('free','subscription','purchase','grant') NOT NULL,
    enrolled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at DATETIME NULL,
    UNIQUE KEY uq_enrollments (user_id, course_id),
    KEY idx_enrollments_course (course_id),
    CONSTRAINT fk_enr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_enr_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lesson_progress (
    user_id BIGINT UNSIGNED NOT NULL,
    lesson_id INT UNSIGNED NOT NULL,
    status ENUM('started','completed') NOT NULL DEFAULT 'started',
    started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at DATETIME NULL,
    last_viewed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    active_seconds INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Visible-tab time reported by heartbeat, capped server-side',
    PRIMARY KEY (user_id, lesson_id),
    KEY idx_lp_lesson (lesson_id),
    KEY idx_lp_completed (user_id, completed_at),
    CONSTRAINT fk_lp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_lp_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE course_progress (
    user_id BIGINT UNSIGNED NOT NULL,
    course_id INT UNSIGNED NOT NULL,
    percent TINYINT UNSIGNED NOT NULL DEFAULT 0,
    lessons_completed SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    lessons_total SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    labs_passed SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    labs_total SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    exam_passed TINYINT(1) NOT NULL DEFAULT 0,
    last_lesson_id INT UNSIGNED NULL,
    completed_at DATETIME NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, course_id),
    KEY idx_cp_course (course_id),
    CONSTRAINT fk_cp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_cp_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
    CONSTRAINT fk_cp_last_lesson FOREIGN KEY (last_lesson_id) REFERENCES lessons(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE learning_activity (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    activity_date DATE NOT NULL,
    type VARCHAR(40) NOT NULL,
    reference_id INT UNSIGNED NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_activity_user_date (user_id, activity_date),
    CONSTRAINT fk_activity_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 003_labs.sql
-- 003: Practical labs, tasks with server-side answer specifications, attempts.

CREATE TABLE labs (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(120) NOT NULL,
    path_id INT UNSIGNED NULL,
    course_id INT UNSIGNED NULL,
    module_id INT UNSIGNED NULL,
    lab_type ENUM('simulation','download','virtual') NOT NULL DEFAULT 'simulation',
    difficulty ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'beginner',
    duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 45,
    pass_percent TINYINT UNSIGNED NOT NULL DEFAULT 70,
    max_attempts SMALLINT UNSIGNED NULL COMMENT 'NULL = unlimited',
    is_required TINYINT(1) NOT NULL DEFAULT 1,
    risk_level ENUM('standard','elevated') NOT NULL DEFAULT 'standard' COMMENT 'Elevated requires a signed safety acknowledgement',
    dataset_file VARCHAR(190) NULL COMMENT 'File under database/content/datasets shown in the in-browser viewer',
    status ENUM('draft','in_review','published','archived') NOT NULL DEFAULT 'draft',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_labs_slug (slug),
    KEY idx_labs_course (course_id),
    KEY idx_labs_status (status),
    CONSTRAINT fk_labs_path FOREIGN KEY (path_id) REFERENCES learning_paths(id) ON DELETE SET NULL,
    CONSTRAINT fk_labs_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL,
    CONSTRAINT fk_labs_module FOREIGN KEY (module_id) REFERENCES modules(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lab_translations (
    lab_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    summary TEXT NOT NULL,
    objectives TEXT NULL,
    scenario MEDIUMTEXT NULL,
    tools TEXT NULL,
    prerequisites TEXT NULL,
    setup MEDIUMTEXT NULL,
    instructions MEDIUMTEXT NULL,
    expected_results TEXT NULL,
    scoring TEXT NULL,
    solution MEDIUMTEXT NULL,
    cleanup TEXT NULL,
    lessons_learned TEXT NULL,
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    PRIMARY KEY (lab_id, locale),
    CONSTRAINT fk_labt_lab FOREIGN KEY (lab_id) REFERENCES labs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lab_tasks (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    lab_id INT UNSIGNED NOT NULL,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    task_type ENUM('text','number','choice','multi','query') NOT NULL DEFAULT 'text',
    points SMALLINT UNSIGNED NOT NULL DEFAULT 10,
    answer_spec JSON NOT NULL COMMENT 'Never sent to the browser',
    KEY idx_lab_tasks_lab (lab_id, sort_order),
    CONSTRAINT fk_lab_tasks_lab FOREIGN KEY (lab_id) REFERENCES labs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lab_task_translations (
    task_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    prompt TEXT NOT NULL,
    hint TEXT NULL,
    explanation TEXT NULL,
    options JSON NULL COMMENT 'Labels for choice/multi tasks keyed by option value',
    PRIMARY KEY (task_id, locale),
    CONSTRAINT fk_ltt_task FOREIGN KEY (task_id) REFERENCES lab_tasks(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lab_attempts (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    lab_id INT UNSIGNED NOT NULL,
    attempt_no SMALLINT UNSIGNED NOT NULL,
    score SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    max_score SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    percent TINYINT UNSIGNED NOT NULL DEFAULT 0,
    passed TINYINT(1) NOT NULL DEFAULT 0,
    results JSON NULL COMMENT 'Per-task correctness, computed server-side',
    answers JSON NULL,
    submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_lab_attempt_no (user_id, lab_id, attempt_no),
    KEY idx_lab_attempts_lab (lab_id),
    CONSTRAINT fk_la_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_la_lab FOREIGN KEY (lab_id) REFERENCES labs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lab_acknowledgements (
    user_id BIGINT UNSIGNED NOT NULL,
    lab_id INT UNSIGNED NOT NULL,
    ip_address VARCHAR(45) NULL,
    accepted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, lab_id),
    CONSTRAINT fk_lack_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_lack_lab FOREIGN KEY (lab_id) REFERENCES labs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE lesson_resources (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    lesson_id INT UNSIGNED NULL,
    lab_id INT UNSIGNED NULL,
    locale ENUM('en','fr') NULL COMMENT 'NULL = language-neutral',
    title VARCHAR(190) NOT NULL,
    storage_path VARCHAR(255) NOT NULL COMMENT 'Relative to storage/uploads or content/datasets; never web-accessible',
    original_name VARCHAR(190) NOT NULL,
    mime_type VARCHAR(120) NOT NULL,
    size_bytes INT UNSIGNED NOT NULL,
    uploaded_by BIGINT UNSIGNED NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_resources_lesson (lesson_id),
    KEY idx_resources_lab (lab_id),
    CONSTRAINT fk_res_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,
    CONSTRAINT fk_res_lab FOREIGN KEY (lab_id) REFERENCES labs(id) ON DELETE CASCADE,
    CONSTRAINT fk_res_user FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 004_assessments.sql
-- 004: Question banks, quizzes/exams, attempts and server-side scored responses.

CREATE TABLE question_banks (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    course_id INT UNSIGNED NOT NULL,
    module_id INT UNSIGNED NULL,
    code VARCHAR(80) NOT NULL,
    name VARCHAR(190) NOT NULL,
    UNIQUE KEY uq_banks_code (code),
    CONSTRAINT fk_banks_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
    CONSTRAINT fk_banks_module FOREIGN KEY (module_id) REFERENCES modules(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE questions (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    bank_id INT UNSIGNED NOT NULL,
    question_type ENUM('single','multiple','true_false','scenario','matching','numeric','text') NOT NULL,
    difficulty ENUM('easy','medium','hard') NOT NULL DEFAULT 'medium',
    points SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    answer_spec JSON NULL COMMENT 'numeric: {value,tolerance}; text: {accepted:[...]} — never sent to the browser',
    status ENUM('active','retired') NOT NULL DEFAULT 'active',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_questions_bank (bank_id, status, difficulty),
    CONSTRAINT fk_questions_bank FOREIGN KEY (bank_id) REFERENCES question_banks(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE question_translations (
    question_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    stem TEXT NOT NULL,
    scenario TEXT NULL,
    explanation TEXT NULL,
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    PRIMARY KEY (question_id, locale),
    CONSTRAINT fk_qt_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE answer_options (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    question_id INT UNSIGNED NOT NULL,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    is_correct TINYINT(1) NOT NULL DEFAULT 0,
    match_key VARCHAR(40) NULL COMMENT 'Matching questions: identifier of the correct right-hand item',
    KEY idx_options_question (question_id),
    CONSTRAINT fk_options_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE answer_option_translations (
    option_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    label TEXT NOT NULL,
    match_label TEXT NULL COMMENT 'Matching questions: right-hand label',
    PRIMARY KEY (option_id, locale),
    CONSTRAINT fk_aot_option FOREIGN KEY (option_id) REFERENCES answer_options(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quizzes (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    course_id INT UNSIGNED NOT NULL,
    module_id INT UNSIGNED NULL,
    slug VARCHAR(120) NOT NULL,
    kind ENUM('knowledge_check','module_quiz','final_exam') NOT NULL DEFAULT 'module_quiz',
    question_count SMALLINT UNSIGNED NOT NULL DEFAULT 10,
    duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 20,
    pass_percent TINYINT UNSIGNED NOT NULL DEFAULT 70,
    max_attempts SMALLINT UNSIGNED NULL COMMENT 'NULL = unlimited',
    retake_cooldown_minutes INT UNSIGNED NOT NULL DEFAULT 0,
    show_explanations ENUM('never','after_submit','after_pass') NOT NULL DEFAULT 'after_submit',
    status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_quizzes_slug (slug),
    KEY idx_quizzes_course (course_id, kind),
    CONSTRAINT fk_quizzes_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
    CONSTRAINT fk_quizzes_module FOREIGN KEY (module_id) REFERENCES modules(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quiz_translations (
    quiz_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    description TEXT NULL,
    translation_status ENUM('missing','draft','in_review','published') NOT NULL DEFAULT 'draft',
    PRIMARY KEY (quiz_id, locale),
    CONSTRAINT fk_quizt_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quiz_banks (
    quiz_id INT UNSIGNED NOT NULL,
    bank_id INT UNSIGNED NOT NULL,
    pick_count SMALLINT UNSIGNED NOT NULL COMMENT 'Random questions drawn from this bank per attempt',
    PRIMARY KEY (quiz_id, bank_id),
    CONSTRAINT fk_qb_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE,
    CONSTRAINT fk_qb_bank FOREIGN KEY (bank_id) REFERENCES question_banks(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quiz_attempts (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    quiz_id INT UNSIGNED NOT NULL,
    attempt_no SMALLINT UNSIGNED NOT NULL,
    status ENUM('in_progress','submitted','expired') NOT NULL DEFAULT 'in_progress',
    locale ENUM('en','fr') NOT NULL DEFAULT 'en',
    started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at DATETIME NOT NULL,
    submitted_at DATETIME NULL,
    score_points SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    max_points SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    percent TINYINT UNSIGNED NOT NULL DEFAULT 0,
    passed TINYINT(1) NOT NULL DEFAULT 0,
    UNIQUE KEY uq_quiz_attempt_no (user_id, quiz_id, attempt_no),
    KEY idx_qa_quiz (quiz_id, status),
    CONSTRAINT fk_qa_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_qa_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quiz_attempt_questions (
    attempt_id BIGINT UNSIGNED NOT NULL,
    question_id INT UNSIGNED NOT NULL,
    sort_order SMALLINT NOT NULL,
    option_order JSON NULL,
    PRIMARY KEY (attempt_id, question_id),
    CONSTRAINT fk_qaq_attempt FOREIGN KEY (attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE,
    CONSTRAINT fk_qaq_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quiz_responses (
    attempt_id BIGINT UNSIGNED NOT NULL,
    question_id INT UNSIGNED NOT NULL,
    response JSON NULL,
    is_correct TINYINT(1) NOT NULL DEFAULT 0,
    points_awarded DECIMAL(6,2) NOT NULL DEFAULT 0,
    PRIMARY KEY (attempt_id, question_id),
    CONSTRAINT fk_qr_attempt FOREIGN KEY (attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE,
    CONSTRAINT fk_qr_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 005_certification_and_sharing.sql
-- 005: Certificates with audit events, achievements, social sharing log.

CREATE TABLE certificates (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    certificate_number VARCHAR(32) NOT NULL,
    user_id BIGINT UNSIGNED NULL COMMENT 'NULL after account erasure; the record stays verifiable',
    course_id INT UNSIGNED NULL,
    path_id INT UNSIGNED NULL,
    holder_name VARCHAR(120) NOT NULL COMMENT 'Snapshot at issue time',
    title_en VARCHAR(190) NOT NULL,
    title_fr VARCHAR(190) NOT NULL,
    path_name_en VARCHAR(160) NULL,
    path_name_fr VARCHAR(160) NULL,
    locale ENUM('en','fr') NOT NULL DEFAULT 'en',
    criteria JSON NOT NULL COMMENT 'Snapshot of the achievement evidence',
    status ENUM('valid','revoked') NOT NULL DEFAULT 'valid',
    issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_at DATETIME NULL,
    revoke_reason VARCHAR(255) NULL,
    signature CHAR(64) NOT NULL COMMENT 'HMAC-SHA256 of immutable fields with APP_KEY',
    is_public TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'Holder opted into a public achievement page',
    share_token CHAR(32) NOT NULL,
    UNIQUE KEY uq_cert_number (certificate_number),
    UNIQUE KEY uq_cert_share (share_token),
    UNIQUE KEY uq_cert_user_course (user_id, course_id),
    KEY idx_cert_status (status),
    CONSTRAINT fk_cert_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_cert_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL,
    CONSTRAINT fk_cert_path FOREIGN KEY (path_id) REFERENCES learning_paths(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE certificate_events (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    certificate_id BIGINT UNSIGNED NOT NULL,
    event ENUM('issued','revoked','reinstated','downloaded') NOT NULL,
    actor_id BIGINT UNSIGNED NULL,
    notes VARCHAR(255) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_cert_events_cert (certificate_id),
    CONSTRAINT fk_ce_cert FOREIGN KEY (certificate_id) REFERENCES certificates(id) ON DELETE CASCADE,
    CONSTRAINT fk_ce_actor FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE achievements (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(60) NOT NULL,
    icon VARCHAR(40) NOT NULL DEFAULT 'award',
    criteria_type ENUM('lessons_completed','labs_passed','exams_passed','streak_days','certificates') NOT NULL,
    threshold INT UNSIGNED NOT NULL,
    UNIQUE KEY uq_achievements_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE achievement_translations (
    achievement_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(120) NOT NULL,
    description VARCHAR(255) NOT NULL,
    PRIMARY KEY (achievement_id, locale),
    CONSTRAINT fk_at_ach FOREIGN KEY (achievement_id) REFERENCES achievements(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE user_achievements (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    achievement_id INT UNSIGNED NOT NULL,
    earned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_public TINYINT(1) NOT NULL DEFAULT 0,
    share_token CHAR(32) NOT NULL,
    UNIQUE KEY uq_user_achievement (user_id, achievement_id),
    UNIQUE KEY uq_ua_share (share_token),
    CONSTRAINT fk_ua_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_ua_ach FOREIGN KEY (achievement_id) REFERENCES achievements(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE social_shares (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    subject_type ENUM('certificate','achievement','profile') NOT NULL,
    subject_id BIGINT UNSIGNED NOT NULL,
    network ENUM('linkedin','facebook','tiktok','copy','download') NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_shares_user (user_id),
    KEY idx_shares_subject (subject_type, subject_id),
    CONSTRAINT fk_shares_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 006_commerce_and_support.sql
-- 006: Plans, subscriptions, orders, payments (no card data ever stored),
-- coupons, access grants, webhooks, support and announcements.

CREATE TABLE plans (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(40) NOT NULL,
    billing_interval ENUM('none','month','year') NOT NULL DEFAULT 'month',
    price_cents INT UNSIGNED NOT NULL DEFAULT 0,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    includes_all_courses TINYINT(1) NOT NULL DEFAULT 1,
    is_contact_sales TINYINT(1) NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    sort_order SMALLINT NOT NULL DEFAULT 0,
    UNIQUE KEY uq_plans_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE plan_translations (
    plan_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    name VARCHAR(80) NOT NULL,
    description VARCHAR(255) NOT NULL,
    features TEXT NOT NULL COMMENT 'One feature per line',
    PRIMARY KEY (plan_id, locale),
    CONSTRAINT fk_plt_plan FOREIGN KEY (plan_id) REFERENCES plans(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE coupons (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(40) NOT NULL,
    percent_off TINYINT UNSIGNED NULL,
    amount_off_cents INT UNSIGNED NULL,
    max_redemptions INT UNSIGNED NULL,
    redeemed_count INT UNSIGNED NOT NULL DEFAULT 0,
    expires_at DATETIME NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_coupons_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE subscriptions (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    plan_id INT UNSIGNED NOT NULL,
    status ENUM('pending','active','canceled','expired') NOT NULL DEFAULT 'pending',
    provider VARCHAR(30) NOT NULL,
    provider_reference VARCHAR(120) NULL,
    current_period_start DATETIME NULL,
    current_period_end DATETIME NULL,
    canceled_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_subs_user (user_id, status),
    CONSTRAINT fk_subs_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_subs_plan FOREIGN KEY (plan_id) REFERENCES plans(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE orders (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reference CHAR(20) NOT NULL,
    user_id BIGINT UNSIGNED NOT NULL,
    item_type ENUM('plan','course','path') NOT NULL,
    item_id INT UNSIGNED NOT NULL,
    subtotal_cents INT UNSIGNED NOT NULL,
    discount_cents INT UNSIGNED NOT NULL DEFAULT 0,
    total_cents INT UNSIGNED NOT NULL,
    currency CHAR(3) NOT NULL,
    coupon_id INT UNSIGNED NULL,
    status ENUM('pending','paid','failed','canceled','refunded') NOT NULL DEFAULT 'pending',
    provider VARCHAR(30) NOT NULL,
    provider_session VARCHAR(190) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    paid_at DATETIME NULL,
    UNIQUE KEY uq_orders_reference (reference),
    KEY idx_orders_user (user_id),
    KEY idx_orders_provider_session (provider_session),
    CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_orders_coupon FOREIGN KEY (coupon_id) REFERENCES coupons(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE payments (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    order_id BIGINT UNSIGNED NOT NULL,
    provider VARCHAR(30) NOT NULL,
    provider_transaction_id VARCHAR(190) NOT NULL,
    amount_cents INT UNSIGNED NOT NULL,
    currency CHAR(3) NOT NULL,
    status ENUM('succeeded','failed','refunded') NOT NULL,
    verified_at DATETIME NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_payments_txn (provider, provider_transaction_id),
    CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE webhook_events (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    provider VARCHAR(30) NOT NULL,
    event_id VARCHAR(190) NOT NULL,
    event_type VARCHAR(120) NOT NULL,
    processed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_webhook_event (provider, event_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE access_grants (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    course_id INT UNSIGNED NULL COMMENT 'NULL with path_id NULL = all courses',
    path_id INT UNSIGNED NULL,
    source ENUM('purchase','admin','enterprise') NOT NULL DEFAULT 'admin',
    granted_by BIGINT UNSIGNED NULL,
    reason VARCHAR(255) NULL,
    expires_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_grants_user (user_id),
    CONSTRAINT fk_grants_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_grants_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
    CONSTRAINT fk_grants_path FOREIGN KEY (path_id) REFERENCES learning_paths(id) ON DELETE CASCADE,
    CONSTRAINT fk_grants_admin FOREIGN KEY (granted_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE support_tickets (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reference CHAR(12) NOT NULL,
    user_id BIGINT UNSIGNED NULL,
    name VARCHAR(120) NOT NULL,
    email VARCHAR(190) NOT NULL,
    category ENUM('general','technical','billing','enterprise','certificate','security') NOT NULL DEFAULT 'general',
    subject VARCHAR(190) NOT NULL,
    message TEXT NOT NULL,
    status ENUM('open','pending','closed') NOT NULL DEFAULT 'open',
    locale ENUM('en','fr') NOT NULL DEFAULT 'en',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_tickets_reference (reference),
    KEY idx_tickets_status (status),
    CONSTRAINT fk_tickets_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ticket_replies (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    ticket_id BIGINT UNSIGNED NOT NULL,
    author_id BIGINT UNSIGNED NULL,
    is_staff TINYINT(1) NOT NULL DEFAULT 0,
    message TEXT NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_replies_ticket (ticket_id),
    CONSTRAINT fk_replies_ticket FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,
    CONSTRAINT fk_replies_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE announcements (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    level ENUM('info','success','warning') NOT NULL DEFAULT 'info',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    starts_at DATETIME NULL,
    ends_at DATETIME NULL,
    created_by BIGINT UNSIGNED NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ann_user FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE announcement_translations (
    announcement_id INT UNSIGNED NOT NULL,
    locale ENUM('en','fr') NOT NULL,
    title VARCHAR(190) NOT NULL,
    body TEXT NOT NULL,
    PRIMARY KEY (announcement_id, locale),
    CONSTRAINT fk_annt_ann FOREIGN KEY (announcement_id) REFERENCES announcements(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
